/**
 * Unresolved call target stubs
 * 388 addresses called by translated code but not
 * detected as functions - typically mid-function entry points.
 * Auto-generated by tools/recomp.
 */

#define RECOMP_GENERATED_CODE
#include "recomp_funcs.h"
#include <math.h>

/* A target inside another function is that function's code entered
 * at the target (entry_stub). The rest: each stub consumes the return address its caller pushed,
 * exactly as a real 'ret' would. An empty body leaves esp 4 bytes
 * low, and the caller then reads every subsequent stack slot off by
 * one - which surfaces far from here, as corrupted callee-saved
 * registers or a garbage local. Args are not popped: the callee's
 * stdcall byte count is read from the target's own bytes where
 * they end in a `ret N` -- guessing cdecl there silently walks
 * esp off by N on every call. */

#include <stdio.h>
#include <stdlib.h>

static int recomp_stub_log_on(void)
{
    static int on = -1;
    if (on < 0) {
        const char *e = getenv("RECOMP_STUB_LOG");
        on = e && *e && *e != '0';
    }
    return on;
}

#define RECOMP_STUB_HIT(va) do { static int _seen; \
    if (!_seen && recomp_stub_log_on()) { _seen = 1; \
        fprintf(stderr, "[STUB] unresolved 0x%08X reached, " \
                "return 0x%08X esp 0x%08X\n", (unsigned)(va), \
                (unsigned)MEM32(g_esp), (unsigned)g_esp); \
        fflush(stderr); } } while (0)

